[package]
autobenches = false
default-run = "pegainfer"
edition = "2024"
license = "Apache-2.0"
name = "pegainfer-server"
version = "0.1.1"

[[bin]]
name = "pegainfer"
path = "src/main.rs"

[dependencies]
anyhow = { workspace = true }
clap = { workspace = true }
log = { workspace = true }
pegainfer-core = { workspace = true }
pegainfer-deepseek-v2-lite = { workspace = true, optional = true }
pegainfer-frontend = { workspace = true }
pegainfer-gemma4 = { workspace = true, optional = true }
pegainfer-glm52 = { workspace = true, optional = true }
pegainfer-k3 = { workspace = true, optional = true }
pegainfer-kimi-k2 = { workspace = true, optional = true }
pegainfer-qwen3 = { workspace = true, optional = true }
pegainfer-qwen35 = { workspace = true, optional = true }
serde_json = { workspace = true }
tokio = { workspace = true, features = ["full"] }
tokio-util = { workspace = true }

[target.'cfg(not(target_env = "msvc"))'.dependencies]
tikv-jemallocator = "0.6"

[features]
# Qwen3-4B is the default model line: pure Rust + CUDA, no Python at build time.
default = ["qwen3"]
qwen3 = ["dep:pegainfer-qwen3"]
# Qwen3.5 pulls in the Triton AOT kernels (Python + Triton at build time).
deepseek-v2-lite = [
  "dep:pegainfer-deepseek-v2-lite",
  "pegainfer-deepseek-v2-lite/deepseek-v2-lite",
]
gemma4 = ["dep:pegainfer-gemma4", "pegainfer-gemma4/gemma4"]
glm52 = ["dep:pegainfer-glm52"]
k3 = ["dep:pegainfer-k3"]
kimi-k2 = ["dep:pegainfer-kimi-k2", "pegainfer-kimi-k2/kimi-k2"]
qwen35 = ["dep:pegainfer-qwen35", "pegainfer-qwen35/qwen35"]

[lints]
workspace = true

